public sealed record Schema(SortedArray<Table> Tables)
{
    /// Every table of a model and what the planter reads of it: views, view columns, modules, permissions, statistics, roles, deploy scripts and refactorlog entries are not read.
    public static Result<Schema> Of(SortedArray<Element> model);
    public Table? Find(Name table);   // binary search over Tables (sorted by Name)
}
public sealed record Table(Name Name, SortedArray<Column> Columns, PrimaryKey? Key, SortedArray<Unique> Uniques, SortedArray<Reference> References, SortedArray<Check> Checks, SortedArray<Trigger> Triggers, Versioning? Versioning) : IComparable<Table>   // by Name
{ public Column? Find(Name column); }
public abstract record Column : IComparable<Column>   // by Ordinal; closed
{
    private Column(int ordinal, Name name, bool nullable) { ... }
    public int Ordinal { get; }  public Name Name { get; }  public bool Nullable { get; }
    public T Match<T>(Func<Stored, T> stored, Func<Computed, T> computed, Func<Generated, T> generated);
    /// A column a row gives a value: its stored type (an alias resolved), the alias it declares, identity, default, sparse, ROWGUIDCOL.
    public sealed record Stored(int Ordinal, Name Name, bool Nullable, ColumnType Type, Name? Alias, Identity? Identity, Default? Default, bool Sparse, bool RowGuid) : Column(Ordinal, Name, Nullable);
    /// AS (expression): SQL Server computes it; Nullable is PersistedNullable when persisted, else Nullable.
    public sealed record Computed(int Ordinal, Name Name, bool Nullable, Value.Script Expression, bool Persisted) : Column(Ordinal, Name, Nullable);
    /// GENERATED ALWAYS: SQL Server fills it (a period column, or another generated kind).
    public sealed record Generated(int Ordinal, Name Name, bool Nullable, ColumnType Type, GeneratedAs As) : Column(Ordinal, Name, Nullable);
}
public enum GeneratedAs { RowStart, RowEnd, Other }
public readonly record struct Identity(long Seed, long Increment);
public sealed record Default(Name? Constraint, Value.Script Expression, Name? Sequence);   // Sequence: the Sequence an ExpressionDependencies target names (PLT-33)
public sealed record KeyColumn(int Position, Name Column, bool Descending) : IComparable<KeyColumn>;   // by Position
public sealed record PrimaryKey(Name? Constraint, SortedArray<KeyColumn> Columns, bool Clustered);
public sealed record Unique(ElementKey Key, Name? Constraint, SortedArray<KeyColumn> Columns, bool IsIndex, Value.Script? Filter, bool Disabled) : IComparable<Unique>;   // by Key
public enum ReferentialAction { NoAction, Cascade, SetNull, SetDefault }
public sealed record Reference(ElementKey Key, Name? Constraint, Name Parent, SortedArray<Reference.Leg> Legs, ReferentialAction OnDelete, ReferentialAction OnUpdate, bool Disabled, bool Optional) : IComparable<Reference>   // by Key
{ public sealed record Leg(int Position, Name Column, Name ParentColumn) : IComparable<Leg>; }
public sealed record Check(ElementKey Key, Name? Constraint, Value.Script Expression, bool Disabled) : IComparable<Check>;
public sealed record Trigger(Name Name, bool Disabled, bool InsteadOf) : IComparable<Trigger>;
public abstract record Versioning   // closed
{
    private Versioning() { }
    public sealed record Current(Name History, Name PeriodStart, Name PeriodEnd) : Versioning;
    public sealed record History(Name Current) : Versioning;
    public T Match<T>(Func<Current, T> current, Func<History, T> history);
}

Schema.Of, O(n log n): (1) index the model by key (ToDictionary(e => e.Key)); group constraint elements by owning table key: Host (PrimaryKeyConstraint, UniqueConstraint, ForeignKeyConstraint, CheckConstraint, DefaultConstraint), IndexedObject (Index with Unique = true only), TriggerObject (DmlTrigger). (2) For each element with Key.Type == "Table" and Key.Parent == null: columns from Relationships "Columns" in Target.Position order, Ordinal = Position + 1. Expression is Value.Script, so Computed. GeneratedAlwaysType member is not "None", so Generated (RowStart and RowEnd from GeneratedAlwaysAsRowStart and GeneratedAlwaysAsRowEnd, else Other). Otherwise Stored with ColumnType.Of(c), then .Stored(model); Alias = declared type's Name when it is two-part; Identity when IsIdentity, parsing IdentitySeed and IdentityIncrement as long with CultureInfo.InvariantCulture (fails: model.identity); Default from the DefaultConstraint whose TargetColumn is this column. (3) Constraint Name = key.Name when key.Parent is null (a named object), else null. KeyColumn.Descending = property "Columns[i].Ascending" is Value.Boolean false (absent means ascending). (4) Reference: Legs = Columns zipped with ForeignColumns by position (unequal counts: model.unresolved); Parent = ForeignTable target's Name. Optional = Disabled || any leg's child column is Nullable, because under MATCH SIMPLE one NULL switches the check off. (5) Versioning.Current from the table's TemporalSystemVersioningHistoryTable target and its RowStart and RowEnd columns; the target table gets Versioning.History(current). (6) Every relationship target Schema.Of follows must be an element of the model, except a one-part DataType key, which is a system type. A missing target, or one keyed Unresolved, is Error("model.unresolved", "<owner key> names <target key>, which the model does not hold.", "Read the model from a published copy or a built package, where every reference resolves."). Trust state is not read here: the model holds none. WP 3.5's trust step reads is_not_trusted through SqlServer.Measure, and S9 decides how.

