public sealed record Order(SortedArray<Order.Step> Tables, SortedArray<Order.Deferral> Deferred, SortedArray<Order.Cycle> Cycles)
{
    public static Order Of(Schema schema);   // total; a cycle is a fact it reports, each with its error
    public sealed record Step(int Position, Name Table) : IComparable<Step>;   // by Position, 0-based
    /// A reference whose columns pass 1 leaves NULL (or plants with the reference suspended) and pass 2 sets.
    public sealed record Deferral(Name Table, ElementKey Reference) : IComparable<Deferral>;
    /// Tables referencing one another through mandatory references; Path in reference order, the first table repeated last only in text.
    public sealed record Cycle(SortedArray<Step> Path) : IComparable<Cycle>
    {
        public Error Error => new("synthetic-copy.cycle", "<t1>, ... reference one another through NOT NULL columns ([dbo].[Egg] → [dbo].[Hen] → [dbo].[Egg]), so no order of INSERTs plants a row in any of them.", "Write one row for each of them into the change's declared witnesses, or make one of those columns nullable.");
    }
}
